// Category A (overlay) — behavior borrowed from react-aria-components, look owned in src.
// Compound component (shadcn model): compose DialogTrigger + DialogContent + DialogHeader +
// DialogTitle + DialogDescription + DialogFooter. The overlay renders in a portal.
//
// Composition contract — required: DialogContent (container) + DialogTitle (accessible name)
// inside a DialogHeader passed as DialogContent's `header` prop. The header and footer are PROPS,
// never children: they render as siblings of the scrolling body, so nothing scrolls under them and
// the panel's one surface shows through (a sticky band inside the scrollport had to repaint that
// surface as a mask, and on a translucent theme the paint stacked). A DialogHeader or DialogFooter
// passed as a child renders as plain body content, without its placement: do not do it.
// Optional: top cover (cover=DialogCover, full-bleed/inset) · header leading (icon or image) ·
// DialogDescription · body slot (children) · footer (DialogFooter) · close button (showCloseButton).
// Enforce through types/composition only (no runtime guard — codebase convention).
import {
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  Heading,
  Modal,
  ModalOverlay,
} from "react-aria-components";
import type {
  DialogTriggerProps as AriaDialogTriggerProps,
  ModalOverlayProps,
} from "react-aria-components";
import { X } from "./icons";
import { ButtonGroup } from "./ButtonGroup";
import { Button } from "./Button";
import { FeaturedIcon } from "./FeaturedIcon";
import { Children, useCallback, useRef, useState } from "react";
import type { CSSProperties, ReactNode, Ref } from "react";
import "./Dialog.css";

/** Make the scrollport focusable only when it actually overflows. An unconditional tabIndex=0
    creates an “unnamed empty tab stop” even in a dialog without scrolling, and draws an inset
    focus ring around the whole panel that looks like a rendering bug (axe does not catch it,
    and it is not visible in screenshots that capture only the default state). */
function useIsScrollable() {
  const [isScrollable, setIsScrollable] = useState(false);
  const observer = useRef<ResizeObserver | null>(null);
  // This must be a callback ref: the panel mounts when the overlay “opens,” but this component does
  // not rerender then, so useEffect + a ref object cannot catch the moment the node attaches (it
  // always runs once with null and finishes).
  const ref = useCallback((el: HTMLDivElement | null) => {
    observer.current?.disconnect();
    observer.current = null;
    if (!el) {
      setIsScrollable(false);
      return;
    }
    const update = () => setIsScrollable(el.scrollHeight > el.clientHeight);
    const ro = new ResizeObserver(update);
    ro.observe(el);
    for (const child of Array.from(el.children)) ro.observe(child);
    observer.current = ro;
    update();
  }, []);
  return [ref, isScrollable] as const;
}

export interface DialogTriggerProps extends AriaDialogTriggerProps {}

export function DialogTrigger(props: DialogTriggerProps) {
  return <AriaDialogTrigger {...props} />;
}

// There is deliberately NO `surface` prop. The overlay layer's treatment — opaque or frosted — is
// the THEME'S (`<html data-surface="translucent">`), and this component reads it and nothing else.
// A dialog whose legibility must win over a photograph needs no exception: the translucent
// surface's opacity is DERIVED as the least opaque step at which text · text-muted · text-brand all
// still clear 4.5:1 composited over pure black AND pure white, so a frosted panel is legible over
// any backdrop by construction. An exception could only buy what ADR-0022 removes: one app shipping
// some frosted overlays and some solid ones. A consumer who truly
// needs one panel to disagree owns the copied source and can say so there.
export interface DialogContentProps
  extends Omit<ModalOverlayProps, "className" | "children" | "style"> {
  /**
   * Panel width, on the brand's `overlay.width` rungs: `small` (confirmation/alert) · `medium`
   * (default) · `large` (gallery/media) · `x-large` (a wide working form) · `2x-large` (a two-column
   * or tall settings panel). Height is auto according to content (capped by max-height).
   *
   * @default "medium"
   */
  width?: "small" | "medium" | "large" | "x-large" | "2x-large";
  /** Whether to show the top-right close (X) button. Defaults to true when a `header` is given
      and false without one, since the close sits in the header's row. It is absolutely positioned
      at the panel frame's top-right (pinned independently of scrolling); with a cover, it floats
      over the image. Set false to hide it for alerts/forced-choice dialogs. */
  showCloseButton?: boolean;
  /** Accessible name of the close (X) button, for a screen that is not in English.
      @default "Close" */
  closeLabel?: string;
  /** Optional top cover — pass `DialogCover` (full-bleed/inset). It stays fixed above the header
      (independently of scrolling); when present, the close button floats over it. Nothing renders
      when it is absent. */
  cover?: ReactNode;
  /** The header — a DialogHeader holding the DialogTitle (the accessible name). Rendered above the
      scrolling body, so it stays in view while a long body scrolls. */
  header?: ReactNode;
  /** The body slot: what scrolls. Headers and footers go in `header` / `footer`, never here. */
  children?: ReactNode;
  /** The footer — a DialogFooter with the actions. Rendered below the scrolling body. */
  footer?: ReactNode;
  /** Optional accessible name — normally unnecessary because DialogTitle provides the name. Use
      only in the rare case with no Title. Forwarded to the role="dialog" element. */
  "aria-label"?: string;
  /** Optional id referencing the accessible name — forwarded to the role="dialog" element. */
  "aria-labelledby"?: string;
  /** Optional id referencing the accessible description — forwarded to the role="dialog" element.
      React Aria links only the title automatically (slot="title" → aria-labelledby), so to have a
      screen reader read the description on open, give DialogDescription an id and pass it here. */
  "aria-describedby"?: string;
  /** Additional class (optional). sd-dialog__content is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the content panel (sd-dialog__content) DOM node (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying content panel (sd-dialog__content) DOM node (the same element as className · style). */
  ref?: Ref<HTMLDivElement>;
}

export function DialogContent({
  width = "medium",
  cover,
  header,
  // No header, no close by default: the close sits in the header's row, and without one it
  // lands on whatever region comes first (measured on FooterOnly: over the primary action).
  showCloseButton = Boolean(header),
  closeLabel = "Close",
  children,
  footer,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-describedby": ariaDescribedBy,
  className,
  style,
  isDismissable = true,
  ref,
  ...props
}: DialogContentProps) {
  const [scrollRef, isScrollable] = useIsScrollable();
  const hasBody = Children.toArray(children).length > 0;
  return (
    <ModalOverlay {...props} isDismissable={isDismissable} className="sd-dialog__overlay">
      <Modal
        ref={ref}
        // No `data-surface` here, at all: the only `[data-surface]` in the system is the one on
        // <html>, which swaps the Sys tokens this panel's background relay reads. Emitting one on
        // the panel would shadow the theme for that instance — the escape hatch this component no
        // longer offers (see the note above the props).
        data-width={width}
        style={style}
        className={className ? `sd-dialog__content ${className}` : "sd-dialog__content"}
      >
        {/* data-has-close drives the header's close-clearance intermediate (contract §6 rule 5):
            the state lives on the panel, the padding is applied on the header child. */}
        <AriaDialog
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          aria-describedby={ariaDescribedBy}
          data-has-close={showCloseButton || undefined}
          // Which regions are present decides each seam (Dialog.css § the three regions).
          data-has-header={header ? true : undefined}
          data-has-body={hasBody || undefined}
          data-has-footer={footer ? true : undefined}
          className="sd-dialog__panel"
        >
          {cover}
          {showCloseButton && (
            <div className="sd-dialog__close">
              <Button slot="close" variant="ghost" isIconOnly size="medium" aria-label={closeLabel}>
                <X aria-hidden size="1em" />
              </Button>
            </div>
          )}
          {header}
          {/* Because the scrollport is a descendant of the role="dialog" element (panel), the
              initial focus React Aria gives the panel does not enable keyboard scrolling
              (PageDown/arrows) — browsers scroll a focused element's scrollable *ancestor*.
              Therefore the scrolling area itself is focusable (the same convention as ScrollArea,
              WCAG 2.1.1), and only while it actually overflows: `data-scrollable` states the same
              fact as `tabIndex` on the same element, so the two cannot diverge. It sits after the
              header in the DOM, so a control in the header is reached before the body. Not
              rendered at all without body content, so a header and footer alone meet at one seam. */}
          {hasBody && (
            <div
              ref={scrollRef}
              className="sd-dialog__scroll"
              data-scrollable={isScrollable || undefined}
              tabIndex={isScrollable ? 0 : undefined}
            >
              <div className="sd-dialog__body">{children}</div>
            </div>
          )}
          {footer}
        </AriaDialog>
      </Modal>
    </ModalOverlay>
  );
}

export interface DialogCoverProps {
  /**
   * Cover variant. `full-bleed` (default) fills to the edges (top corners use the panel rounding) ·
   * `inset` has 16px top/left/right spacing (bottom touches the header) + medium rounding (an image
   * contained in a card).
   *
   * @default "full-bleed"
   */
  variant?: "full-bleed" | "inset";
  /** Optional cover content — image/gradient/embed. It is **decorative** and receives aria-hidden,
      so do not put focusable or meaningful content in it. */
  children?: ReactNode;
  /** Additional class (optional). sd-dialog__cover is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the cover <div> (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying cover <div> DOM node (the same element as className · style). */
  ref?: Ref<HTMLDivElement>;
}

export function DialogCover({
  variant = "full-bleed",
  children,
  className,
  style,
  ref,
}: DialogCoverProps) {
  return (
    <div
      ref={ref}
      aria-hidden="true"
      data-variant={variant}
      style={style}
      className={className ? `sd-dialog__cover ${className}` : "sd-dialog__cover"}
    >
      {children}
    </div>
  );
}

export interface DialogHeaderBaseProps {
  /**
   * Alignment axis. `center` centers the leading visual · title · description (alert/confirmation
   * forms). Defaults to `start`.
   *
   * @default "start"
   */
  align?: "start" | "center";
}

/**
 * DialogHeader props.
 *
 * There can be only one leading visual, an icon **or** an image — because the header is a vertical
 * column, passing both silently breaks it by stacking them. Therefore exclusivity is enforced at
 * the **type level**, not merely in documentation (contract §2 discriminated-union carve-out — the
 * same rationale as Button). There is no runtime guard.
 */
export type DialogHeaderProps = DialogHeaderBaseProps &
  (
    | {
        /** Optional leading icon — a glyph contained in the shared `FeaturedIcon` plate (neutral
            rounded box). Pass `size="1em"` and the plate determines its size from its own tokens. */
        icon?: ReactNode;
        image?: never;
      }
    | {
        /** Optional leading image — a photo/thumbnail (avatar · logo) that fills the same
            `FeaturedIcon` plate. Give the media the `sd-featured-icon__media` class to crop it to
            the plate (object-fit: cover). */
        image?: ReactNode;
        icon?: never;
      }
  ) & {
    /** Header content (optional wrapper) — normally the required DialogTitle (+ optional DialogDescription). */
    children?: ReactNode;
    /** Additional class (optional). sd-dialog__header is always preserved. */
    className?: string;
    /** Optional inline style — forwarded to the header <div> (the same element as className). */
    style?: CSSProperties;
    /** Forwarded to the underlying <div> DOM node. */
    ref?: Ref<HTMLDivElement>;
  };

export function DialogHeader({
  align = "start",
  icon,
  image,
  children,
  className,
  style,
  ref,
}: DialogHeaderProps) {
  return (
    <div
      ref={ref}
      data-align={align}
      style={style}
      className={className ? `sd-dialog__header ${className}` : "sd-dialog__header"}
    >
      {/* Both leading visuals are the shared FeaturedIcon plate — it owns the geometry (size,
          radius, glyph size, clipping) and sets no colour, so the glyph keeps inheriting the
          panel foreground. `sunken` because the plate sits on the panel's plain white surface,
          where Alert's sits on a status tint (`raised`). */}
      {icon && (
        <FeaturedIcon aria-hidden="true" size="large" tone="sunken" className="sd-dialog__icon">
          {icon}
        </FeaturedIcon>
      )}
      {image && (
        <FeaturedIcon aria-hidden="true" size="large" tone="sunken" className="sd-dialog__image">
          {image}
        </FeaturedIcon>
      )}
      <div className="sd-dialog__header-text">{children}</div>
    </div>
  );
}

export interface DialogTitleProps {
  /** Title content. **Required** — becomes the dialog's accessible name (slot="title" → aria-labelledby). */
  children?: ReactNode;
  /** Additional class (optional). sd-dialog__title is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the title heading (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying heading DOM node (the same element as className · style). */
  ref?: Ref<HTMLHeadingElement>;
}

export function DialogTitle({ className, style, ref, ...props }: DialogTitleProps) {
  return (
    <Heading
      {...props}
      ref={ref}
      style={style}
      slot="title"
      className={
        className
          ? `sd-dialog__title sd-type-title-medium ${className}`
          : "sd-dialog__title sd-type-title-medium"
      }
    />
  );
}

export interface DialogDescriptionProps {
  /** Optional description content — supporting text below the title. */
  children?: ReactNode;
  /** Optional element id — pass it to DialogContent's `aria-describedby` to link the accessible description. */
  id?: string;
  /** Additional class (optional). sd-dialog__description is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the description <p> (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying <p> DOM node (the same element as className · style). */
  ref?: Ref<HTMLParagraphElement>;
}

export function DialogDescription({ className, style, ref, ...props }: DialogDescriptionProps) {
  return (
    <p
      {...props}
      ref={ref}
      style={style}
      className={
        className
          ? `sd-dialog__description sd-type-body-medium ${className}`
          : "sd-dialog__description sd-type-body-medium"
      }
    />
  );
}

export interface DialogFooterProps {
  /**
   * Action layout — `end` (default) right-aligns · buttons hug; `center` splits evenly left/right
   * (equal-width filled buttons) · centers description; `stack` makes a vertical full-width stack ·
   * centers description under it; `fill` keeps one row at every size, the aside action hugging and the
   * primary filling the rest. (layout owns only action-button placement.) The same axis as DrawerFooter
   * — sibling overlays use the same footer model.
   *
   * @default "end"
   */
  layout?: "end" | "center" | "stack" | "fill";
  /** Optional help/fine print, spanning the full width. Above the actions in a row layout (`end`,
      `center`, `fill`), where it is the fine print the actions act on (for example, “Billing begins
      after the trial ends”); directly UNDER the action in `stack`, where it is the reassurance line
      that answers the action, read after it. It can be used with every layout. */
  description?: ReactNode;
  /** Optional footer content — action buttons, etc. */
  children?: ReactNode;
  /** Additional class (optional). sd-dialog__footer is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the footer <div> (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying <div> DOM node (the same element as className · style). */
  ref?: Ref<HTMLDivElement>;
}

export function DialogFooter({
  layout = "end",
  description,
  children,
  className,
  style,
  ref,
}: DialogFooterProps) {
  // One rung below the header `description` it closes — CONTRASTIVE, and both are on screen at once
  // (`naming-convention.md` § The size axis defaults to `medium`).
  const note = description && (
    <p data-layout={layout} className="sd-dialog__footer-description sd-type-body-small">
      {description}
    </p>
  );
  // A stack's line follows its action in the DOM as on screen, so it is read after it too.
  const isUnder = layout === "stack";
  return (
    <div
      ref={ref}
      style={style}
      className={className ? `sd-dialog__footer ${className}` : "sd-dialog__footer"}
    >
      {!isUnder && note}
      <ButtonGroup layout={layout}>{children}</ButtonGroup>
      {isUnder && note}
    </div>
  );
}

/* Dialog.css — .sd-dialog__* (포털 오버레이)
   규칙: sd- 프리픽스 / 평평한 단일 클래스 / 상태는 react-aria data-* / Cmp 토큰 참조. */
.sd-dialog__overlay {
  position: fixed;
  inset: 0;
  z-index: var(--sd-dialog-overlay-z-index);
  display: grid;
  place-items: center;
  background: var(--sd-dialog-overlay-background);
  padding: var(--sd-dialog-overlay-padding);
}

.sd-dialog__overlay[data-entering] {
  animation: sd-dialog-overlay-enter var(--sd-dialog-animation-duration) var(--sd-easing-decelerate);
}

.sd-dialog__overlay[data-exiting] {
  animation: sd-dialog-overlay-exit var(--sd-dialog-animation-duration) var(--sd-easing-accelerate);
}

/* content — the outer panel frame (border/radius/shadow/width + the enter/exit animation target).
   A flex column holding the single `panel`; overflow:hidden clips the radius so the cover's top
   corners round and nothing spills past the frame. */
.sd-dialog__content {
  display: flex;
  flex-direction: column;
  width: min(var(--sd-dialog-content-width-medium), 100%);
  max-height: var(--sd-dialog-content-max-height);
  overflow: hidden;
  /* Surface treatment — the panel's paper and its blur, read straight from the THEME and from
     nothing else. `--sd-dialog-content-background` and `-backdrop-filter` are this component's
     relays for the Sys `surface-treatment.overlay-*` pair, which `[data-surface]` on <html> swaps
     (tokens.css). Under a standard theme they resolve to the opaque overlay surface and `none` (`backdrop-filter`'s initial value, which
     creates no backdrop root or containing block — so an opaque dialog still pays nothing).

     NO per-instance departure is offered, and that is the rule, not an omission: a glass theme means
     every overlay is glass, so no app ships some frosted dialogs and some solid ones (ADR-0022). A
     dialog whose legibility must win over a photograph needs no exception either, because the
     CONTRACT covers it: the translucent surface's opacity is DERIVED as the least
     opaque step at which text, text-muted and text-brand all still clear 4.5:1 composited over pure
     black AND pure white (plan-color.mjs § the translucent overlay surface). A frosted panel is
     therefore legible over ANY backdrop by construction — and stays legible where `backdrop-filter`
     is unsupported or disabled, since the filter is the enhancement and the surface carries the
     contract. All an exception could still buy was the incoherence ADR-0022 exists to remove.

     -webkit- prefix for Safari, which shipped the prefixed form long before the unprefixed one. It
     must be declared on every element that paints the treatment (here and on the two bands below),
     since a var() carries a value, not a property name.

     The header and footer are siblings of the scrolling body (DialogContent's `header` / `footer`
     props), so nothing scrolls under them and they paint no surface of their own: the panel's one
     surface shows through all three regions. Sticky bands INSIDE the scrollport would have to
     repaint this surface as a mask, which on a translucent theme composites to a near-opaque band
     (0.90 over 0.90 = 0.99), and no CSS treatment fixes that, because paint always stacks. */
  background: var(--sd-dialog-content-background);
  -webkit-backdrop-filter: var(--sd-dialog-content-backdrop-filter);
  backdrop-filter: var(--sd-dialog-content-backdrop-filter);
  color: var(--sd-dialog-content-foreground);
  border: var(--sd-dialog-content-border-width) solid var(--sd-dialog-content-border);
  border-radius: var(--sd-dialog-content-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  box-shadow: var(--sd-dialog-content-shadow);
}

/* panel — the role="dialog" element + the layout column. Fills the frame and stacks the cover
   (fixed), close (absolute → this box, so it stays put), and the scrolling body. It is the
   positioning context for the pinned close and holds it *inside* the dialog (so `slot="close"`
   wiring + a11y are correct); the body it contains owns the scroll, not this column. */
.sd-dialog__panel {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  outline: none;
  /* 8 on BOTH sides. Reserving the close button's own width here (`--sd-<c>-close-size`, 40) would
     make the header read as a 40px inset against the panel's other content. The close floats above
     the title, and the title's own clearance (below) keeps a long one from passing beneath it. */
}
/* No `[data-surface]` rule on this panel — deliberately. The only `[data-surface]` in the system is
   the one on <html> (tokens.css), which swaps the Sys pair the base rule above already reads. A
   per-instance override here would let one dialog disagree with its theme, and the two cases it
   would serve are both closed: `standard` is unnecessary (the derived opacity keeps a frosted panel
   at 4.5:1 over any backdrop — see the base rule), and `translucent` under a solid theme is the
   mixed-overlay incoherence ADR-0022 removed. If a consumer genuinely needs one panel to disagree,
   they own this copied file and can add the rule there — that is what copy-paste distribution is
   for, and it keeps the divergence visible in their repo instead of in our API. */

/* width scale (DialogContent `width`): small (confirm/alert) · medium (default) ·
   large (gallery/media) · x-large (a wide working form) · 2x-large (a two-column panel). Height stays content-driven; `min(…, 100%)` handles mobile. */
.sd-dialog__content[data-width="small"] {
  width: min(var(--sd-dialog-content-width-small), 100%);
}
.sd-dialog__content[data-width="large"] {
  width: min(var(--sd-dialog-content-width-large), 100%);
}
.sd-dialog__content[data-width="x-large"] {
  width: min(var(--sd-dialog-content-width-x-large), 100%);
}
.sd-dialog__content[data-width="2x-large"] {
  width: min(var(--sd-dialog-content-width-2x-large), 100%);
}

.sd-dialog__content[data-entering] {
  animation: sd-dialog-content-enter var(--sd-dialog-animation-duration) var(--sd-easing-decelerate);
}

.sd-dialog__content[data-exiting] {
  animation: sd-dialog-content-exit var(--sd-dialog-animation-duration) var(--sd-easing-accelerate);
}

/* scroll — the scrollport (the only scroller), between the header and the footer. The padded body
   inside owns the content insets; the scrollport's only padding is the focus-ring room below. */
.sd-dialog__scroll {
  /* §6-3: the DS ring is drawn below, so the UA outline is reset on the BASE rule —
     inside the focus rule it lands too late and the OS accent paints alongside ours. */
  outline: none;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  /* Under a header the body's block-start padding is 0, so a field that opens the body sat flush
     against this clip and lost the top of its focus ring (CommandMenu's search, FormDialog's first
     field). Ring room with the margin given straight back, as `.sd-tabs__scroll` does, so no seam
     moves (contract §6 rule 7). */
  padding-block: var(--sd-state-focus-ring-width);
  margin-block: calc(-1 * var(--sd-state-focus-ring-width));
}
/* The three regions — header, body, footer — are siblings, and which of them are present decides
   each seam, so every combination lands on the spacing the header and footer had when they sat
   inside the body: header→content is the body `gap`, content→footer is the `gap` plus the footer's
   own block-start, and a header meeting a footer directly (no body) keeps that same seam. The
   panel carries the three `data-has-*` facts; the parts read these relays (contract §6 rule 5).
   Each part's DEFAULT is the full composition, header + body + footer, which is what a Figma master
   draws, so the projection reads the default branch; the rules below adjust only for a missing
   region. */
.sd-dialog__panel:not([data-has-body]):not([data-has-footer]) {
  --sd-dialog-header-padding-block-end-current: var(--sd-dialog-body-padding-block);
}
.sd-dialog__panel:not([data-has-header]) {
  --sd-dialog-body-padding-block-start-current: var(--sd-dialog-body-padding-block);
}
.sd-dialog__panel:not([data-has-footer]) {
  --sd-dialog-body-padding-block-end-current: var(--sd-dialog-body-padding-block);
}
.sd-dialog__panel:not([data-has-header]):not([data-has-body]) {
  --sd-dialog-footer-padding-block-start-current: calc(var(--sd-dialog-body-padding-block) + var(--sd-dialog-footer-padding-block-start));
}
/* The scrollport is focusable (keyboard scrolling, WCAG 2.1.1), so it needs a visible focus
   indicator meeting the 3:1 contract — the UA default ring is both off-palette and too low in
   dark. Inset, because the frame's overflow:hidden would clip an outward ring. */
.sd-dialog__scroll:focus-visible {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* body — the padded content column inside the scrollport. Its block padding gives way to the
   header and footer seams (the relays above); inline padding stays here so slotted media can go
   full-bleed. */
.sd-dialog__body {
  display: flex;
  flex-direction: column;
  gap: var(--sd-dialog-body-gap);
  padding-block-start: var(--sd-dialog-body-padding-block-start-current, 0);
  padding-block-end: var(--sd-dialog-body-padding-block-end-current, var(--sd-dialog-body-gap));
  padding-inline: var(--sd-dialog-body-padding-inline);
}


/* cover — media banner above the header (optional; a DialogCover passed to DialogContent's `cover`).
   Fixed: it sits outside the scrolling body, so it stays while the body scrolls and the close button
   floats over it. Two variants:
   - full-bleed (default) — spans edge-to-edge (no margin); the panel's radius + overflow round its
     top corners.
   - inset — a floating card image: 16px inset on top + sides (bottom sits flush against the header)
     + its own medium radius. */
.sd-dialog__cover {
  flex-shrink: 0;
  overflow: hidden;
  line-height: 0;
}
.sd-dialog__cover[data-variant="inset"] {
  margin: var(--sd-dialog-cover-inset) var(--sd-dialog-cover-inset) 0;
  border-radius: var(--sd-dialog-cover-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}

/* header — above the scrolling body, a sibling of it, so it stays in view while a long body slot
   scrolls and paints nothing of its own. `flex-shrink: 0`, like the cover: the scrollport is what
   gives way when the panel is capped. The band takes the body's inset on its sides and top, and
   `__header-text` adds the text inset inside it, since the panel draws that text on its own surface
   (component-contract.md §6 rule 8); block-end is the seam to what follows (see the relays above). The end
   side reserves nothing for the close: that would read as a 40px inset against the panel's other
   content, so the clearance sits on the title instead (`__title` below). */
.sd-dialog__header {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--sd-dialog-header-gap);
  /* The header is one band of the panel: the panel's own surface padding on its sides and top, the
     same token the body and footer spend. The text group inside adds the text inset, and a leading
     plate takes the band's edge as a box does (component-contract.md §6 rule 8). */
  padding-block-start: var(--sd-dialog-body-padding-block);
  padding-block-end: var(--sd-dialog-header-padding-block-end-current, var(--sd-dialog-body-gap));
  padding-inline: var(--sd-dialog-body-padding-inline);
}
/* center alignment (alert/confirm dialogs) — icon·title·description centered. The close clearance is
   mirrored onto the start side so the centered content stays optically centered. */
.sd-dialog__header[data-align="center"] {
  align-items: center;
  text-align: center;
}
/* title + description group — tighter gap than the icon↔text header gap. */
.sd-dialog__header-text {
  display: flex;
  flex-direction: column;
  gap: var(--sd-dialog-header-text-gap);
  align-self: stretch;
  /* Text the panel always draws on its own surface takes the text inset (component-contract.md §6
     rule 8, component-owned text); a leading plate stays on the band's edge, as a box does. Inline
     only: `text-inset.block` is spent by no part. */
  padding-inline: var(--sd-dialog-header-padding-inline-start);
}
/* The two mutually-exclusive leading visuals (`icon` / `image`) carry no rules of their own: both
   render the shared FeaturedIcon plate, which owns the square, the radius, the neutral fill, the
   glyph size and the media clipping — including the `flex: 0 0 auto` that keeps the plate from
   shrinking in this header row. Only the BEM part class stays, as the Figma layer name. */

/* Panel text wraps rather than overflowing: the panel is a fixed-width scrollport, so a long
   unbreakable string (a URL, a filename, a token) would otherwise force horizontal scroll.
   `anywhere` (not `break-word`) so the break also lowers the intrinsic min-content width, which is
   what flex sizing measures. */
/* Close clearance lives HERE, on the title alone — not on the header box, which stays 8/8. The
   close is `position: absolute` over the panel corner and reserves no room, so without this a long
   title runs straight under it. Only the title shares the close's line — the
   description and body keep their 8 inset, which is exactly what putting the reservation on the
   header would have broken again.
   The state (`[data-has-close]`) sits on the panel and the padding applies on this child, via a
   local intermediate — contract §6 rule 5, no descendant combinator. The default is 0 so a
   `showCloseButton={false}` dialog gets no phantom inset. */
.sd-dialog__title {
  margin: 0;
  color: var(--sd-dialog-title-foreground);
  overflow-wrap: anywhere;
  padding-inline-end: var(--sd-dialog-title-close-clearance-current, 0);
  /* Centered headers mirror the clearance onto the start side, or the title is centred inside a
     box that is 28px narrower on one end and drifts ~14px toward the start. The header rule below
     only re-declares the intermediate — the value still comes from the panel, so a centered header
     with NO close button keeps 0 on both sides. */
  padding-inline-start: var(--sd-dialog-title-close-clearance-start-current, 0);
}
.sd-dialog__header[data-align="center"] {
  --sd-dialog-title-close-clearance-start-current: var(--sd-dialog-title-close-clearance-current, 0);
}
.sd-dialog__panel[data-has-close] {
  /* how far the title must retreat from where it sits today: the close occupies
     `inset + size` from the panel's inner edge, and the title already starts
     `body-padding + header-padding` in from it. */
  --sd-dialog-title-close-clearance-current: calc(
    var(--sd-dialog-close-inset) + var(--sd-dialog-close-size) -
    var(--sd-dialog-body-padding-inline) - var(--sd-dialog-header-padding-inline-start)
  );
}
.sd-dialog__description {
  margin: 0;
  /* The header-text column already stands its text one inset in (its title measures the close
     clearance from that edge), so the description's role adds none of its own. */
  padding-inline: 0;
  color: var(--sd-dialog-description-foreground);
  overflow-wrap: anywhere;
}

/* Close = the shared Button (variant="ghost", isIconOnly) in a positioned wrapper — all look/state
   (fill, radius, size, state-layer, focus ring) comes from Button; the wrapper only positions it.
   Pinned to the panel's top-inline-end corner (absolute; `.sd-dialog__panel` is the positioning
   context), so it stays put while the body scrolls and floats over the cover (or the header
   when there's no cover). The inset clears the panel radius. The header no longer reserves
   matching inline room — see the header rule. */
.sd-dialog__close {
  position: absolute;
  top: var(--sd-dialog-close-inset);
  inset-inline-end: var(--sd-dialog-close-inset);
  /* above the cover, which a consumer may position; over the header it wins by being positioned. */
  z-index: 2;
  display: inline-flex;
}

/* footer — below the scrolling body, a sibling of it: an optional helper `description` (full-width,
   above the actions row, or under the action in `stack`) + the actions row. Same two-part shape as
   DrawerFooter — the sibling overlays share one footer model. The actions row owns the layout (end/center/stack); the description is
   orthogonal. Inline it sits at the body's inset, full-width like the body slot. Block-start is its
   own inset after a header or body, and the body's block inset plus its own when it is the panel's
   first region; block-end is the body's inset, so the buttons clear the panel's rounded corner. */
.sd-dialog__footer {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: var(--sd-dialog-footer-gap);
  padding-block-start: var(--sd-dialog-footer-padding-block-start-current, var(--sd-dialog-footer-padding-block-start));
  padding-block-end: var(--sd-dialog-body-padding-block);
  padding-inline: var(--sd-dialog-body-padding-inline);
}
/* helper / fine-print line above the actions, or under them in `stack` (muted; reuses the
   description color). It aligns
   with the actions: left for end (default), centered for the symmetric center/stack layouts.
   The layout is set on the description element itself (same-element selector, no child combinator). */
.sd-dialog__footer-description {
  margin: 0;
  color: var(--sd-dialog-description-foreground);
  overflow-wrap: anywhere;
  /* The same inset the header title takes: text the panel draws on its own surface. */
  padding-inline: var(--sd-dialog-footer-description-padding-inline);
}
.sd-dialog__footer-description[data-layout="center"],
.sd-dialog__footer-description[data-layout="stack"] {
  text-align: center;
}
/* actions row layout cases: end (default) right-aligned · center equal side-by-side (grid, no
   child selectors) · stack full-width vertical. The button↔button gap is its own token, a rung
   tighter than the footer's description↔actions gap on the column, so the buttons read as one
   group inside the footer rather than as siblings of the description. */



/* mobile: the default (end) actions stack full-width, primary (last child) on top. */
/* mobile-first (naming-convention § Modes): the stacked, full-width action list is the BASE —
   on a narrow panel a side-by-side row would squeeze the buttons — and the `medium` step restores
   the right-aligned row. Never a `max-width` query: that would author desktop as the base and
   invert the ladder every other responsive rule in the system follows. */
