}

@keyframes sd-dialog-overlay-enter {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes sd-dialog-overlay-exit {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes sd-dialog-content-enter {
  from {
    opacity: 0;
    transform: translateY(var(--sd-dialog-content-translate-enter));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sd-dialog-content-exit {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(var(--sd-dialog-content-translate-exit));
  }
}

@media (prefers-reduced-motion: reduce) {
  .sd-dialog__content[data-entering],
  .sd-dialog__content[data-exiting] {
    animation: none;
  }
}
